import struct, os, subprocess, itertools, random
def tag(t,ty,c,v): return struct.pack('<HHII',t,ty,c,v)
def build(path, W,H,bits,photo,samples,orient=None,extras=None,cmap=False,planar=1):
    cm = b''.join(struct.pack('<H',i*257) for i in range(256))*3 if cmap else b''
    pix = bytes(max(1,W*H*samples*(bits//8)))
    hdr=b'II*\x00'+struct.pack('<I',8)
    entries=[]; data=bytearray()
    ntag=9+(1 if cmap else 0)+(1 if orient else 0)+(1 if extras else 0)
    base=8+2+12*ntag+4
    def add(b):
        off=base+len(data); data.extend(b)
        if len(data)%2: data.append(0)
        return off
    entries.append(tag(256,3,1,W));entries.append(tag(257,3,1,H))
    entries.append(tag(258,3,1,bits));entries.append(tag(259,3,1,1))
    entries.append(tag(262,3,1,photo))
    entries.append(tag(273,4,1,add(pix)))
    if orient: entries.append(tag(274,3,1,orient))
    entries.append(tag(277,3,1,samples));entries.append(tag(278,3,1,H))
    entries.append(tag(279,4,1,len(pix)))
    if cmap: entries.append(tag(320,3,768,add(cm)))
    if extras: entries.append(tag(338,3,1,extras))
    entries.sort(key=lambda e:struct.unpack('<H',e[:2])[0])
    ifd=struct.pack('<H',len(entries))+b''.join(entries)+struct.pack('<I',0)
    open(path,'wb').write(hdr+ifd+bytes(data))

VUL='/out-vul/coder_PTIF_fuzzer'
cases=[]
i=0
for photo in [0,1,2,3,6,7,8,9,10]:
  for orient in [None,1,5,6,7,8]:
    for bits in [8,16]:
      for cmap in ([True] if photo==3 else [False]):
        for samples in ([1,2] if cmap else [1,3,4]):
          p=f'/tmp/fz/{i}.tif'; i+=1
          cases.append((p,photo,orient,bits,samples,cmap))
os.makedirs('/tmp/fz',exist_ok=True)
for (p,photo,orient,bits,samples,cmap) in cases:
    try: build(p,32,32,bits,photo,samples,orient=orient,cmap=cmap)
    except: continue
    r=subprocess.run([VUL,p],capture_output=True)
    if r.returncode not in (0,):
        print(f'CRASH rc={r.returncode} photo={photo} orient={orient} bits={bits} samples={samples} cmap={cmap} file={p}')
        print(r.stderr.decode()[:300])
print('done', len(cases))
PYEOF
